27	namespace fs = std::filesystem;
28	
29	namespace andes_sim {
30	namespace {
31	
32	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
33	// success; on failure prints an error tagged with `ctx` and returns "". The
34	// existence check is here, at the shared resolver, so a missing path fails
35	// with a clear "ELF not found" instead of being handed to the engine (e.g.
36	// qemu's cryptic "Unable to find the RISC-V BIOS").
37	std::string abs_elf(const std::string& path, const std::string& ctx) {
38	  std::error_code ec;
39	  fs::path abs = fs::absolute(path, ec);
40	  if (ec) {
41	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
42	                 ctx.c_str(), path.c_str());
43	    return "";
44	  }
45	  if (!fs::is_regular_file(abs, ec)) {
46	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
47	                 path.c_str());
48	    return "";
49	  }
50	  return abs.string();
51	}
52	
53	// Validate the lone-ELF positional shape the standalone models require: print
54	// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
55	int check_one_elf(const Cli& cli, const char* model) {
56	  if (cli.positional.empty()) {
57	    std::fprintf(stderr,
58	                 "andesim run --mode %s: missing ELF (the workload to run; "
59	                 "e.g. a tests/fixtures/<name>.elf)\n",
60	                 model);
61	    return 2;
62	  }
63	  if (cli.positional.size() > 1) {
64	    std::fprintf(stderr,
65	                 "andesim run --mode %s: unexpected argument '%s' "
66	                 "(engine args go after --)\n",
67	                 model, cli.positional[1].c_str());
68	    return 2;
69	  }
70	  return 0;
71	}
72	
73	// The standalone spine: take a single ELF, then run the resolved engine
74	// standalone with the post-`--` args appended verbatim (exec_passthrough --
75	// inherit stdio, no timeout, propagate the exit code, so an interactive
76	// gdbstub / monitor / semihosting console works unchanged). The per-model
77	// engine + selection are resolved by the caller; `model` here only labels
78	// the positional diagnostics.
79	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
80	                   const char* model, const std::vector<std::string>& extra = {}) {
81	  if (int rc = check_one_elf(cli, model)) return rc;
82	  // QEMU's -bios flag searches its data directory for relative paths rather
83	  // than the CWD; resolve to absolute so the engine finds the ELF.
84	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
85	  if (elf.empty()) return 2;
86	  // `extra` (framework flags, e.g. fast's -m) precedes the post-`--` args, so a
87	  // user's own flag after `--` wins.
88	  std::vector<std::string> args = extra;
89	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
90	  std::string err;
91	  const std::vector<std::string> argv =
92	      passthrough_argv(eng, "standalone", elf, args, err);
93	  if (!err.empty()) {
94	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
95	    return 2;
96	  }
97	  return exec_passthrough(argv);
98	}
99	
100	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
101	// only the built-in qemu descriptor, so it resolves that directly rather than
102	// discover_engines(), which would spawn a --describe subprocess per Verilator
103	// build only to discard them all here.
104	int run_fast(const Cli& cli) {
105	  // fast is QEMU-only; an explicit engine must name it.
106	  if (!cli.engine.empty() && cli.engine != kQemuId) {
107	    std::fprintf(stderr,
108	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
109	                 cli.engine.c_str());
110	    return 2;
111	  }
112	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
113	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
114	  std::string err;
115	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
116	  if (!err.empty()) {
117	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
118	    return 2;
119	  }
120	  return run_standalone(cli, builtin_qemu(), "fast", extra);
121	}
122	
123	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
124	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
125	// engine's own output. Unlike fast, this must discover the vsim build(s) to
126	// resolve the engine (explicit --engine, else the sole one).
127	int run_accurate(const Cli& cli) {
128	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
129	  // --describe subprocess per vsim build only to fail on the argument.
130	  if (int rc = check_one_elf(cli, "cycle")) return rc;
131	  // --mem-size is validated but has nothing to size: the cycle engine always
132	  // models its full DRAM window. Say so instead of silently ignoring it.
133	  if (!cli.mem_size.empty()) {
134	    std::string se;
135	    if (parse_size(cli.mem_size, se); !se.empty()) {
136	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
137	                   se.c_str());
138	      return 2;
139	    }
140	    std::fprintf(stderr,
141	                 "[andesim] --mem-size: the cycle engine models its full "
142	                 "DRAM window; nothing to size\n");
143	  }
144	  Discovery disc = discover_engines();
145	  std::string err;
146	  const EngineDescriptor* eng =
147	      resolve_accurate_engine(disc.engines, cli.engine, err);
148	  if (!eng) {
149	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
150	    // Surface why an expected engine may be absent (failed --describe, etc.).
151	    for (const std::string& w : disc.warnings)
152	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
153	    return 2;
154	  }
155	  return run_standalone(cli, *eng, "cycle");
156	}
157	
158	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
159	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
160	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
161	// driver's tests/e2e.sh delegation with a single window-cycle line.
162	int run_hybrid(const Cli& cli) {
163	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
164	  auto fail = [](const std::string& msg) {
165	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
166	    return 2;
167	  };
168	
169	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
170	
171	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
172	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
173	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
174	  const std::string elf_path = abs_elf(cli.positional[0], "--mode hybrid");
175	  if (elf_path.empty()) return 2;
176	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
177	
178	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
179	  // mistake fails fast without spawning a --describe per Verilator build.
180	  std::string err;
181	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
182	  if (!err.empty()) return fail(err);
183	
184	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
185	  if (!err.empty()) return fail(err);
186	
187	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
188	  if (!cli.mem_size.empty()) {
189	    std::string se;
190	    mem = parse_size(cli.mem_size, se);
191	    if (!se.empty()) return fail("--mem-size: " + se);
192	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the mmap backend doubles
193	    // as guest RAM here. Failing now beats allocating a huge mmap file first and
194	    // letting QEMU die late.
195	    if (mem > 2LL * 1024 * 1024 * 1024)
196	      return fail("--mem-size " + cli.mem_size +
197	                  " exceeds the AE350 DRAM window (2G)");
198	  }
199	
200	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
201	  // or the sole cycle-accurate engine (reusing the F8 selector).
202	  Discovery disc = discover_engines();
203	  const EngineDescriptor* acc =
204	      resolve_accurate_engine(disc.engines, cli.engine, err);
205	  if (!acc) {
206	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
207	    for (const std::string& w : disc.warnings)
208	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
209	    return 2;
210	  }
211	
212	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
213	  // cannot share architectural state with the rv64 fast leg).
214	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
215	
216	  Plan plan;
217	  plan.elf = elf_path;
218	  plan.mem_size = mem;
219	  Step qemu_step{kQemuId, "fast-leg", trig};
220	  Step vsim_step{acc->id, "accurate-leg", trig};
221	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
222	  plan.steps = {qemu_step, vsim_step};
223	
224	  // Banner to stderr so the window-cycle result stands alone on stdout.
225	  // vlen is the synced value the fast leg inherits from the engine.
226	  std::fprintf(stderr,
227	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
228	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
229	               elf.stem().string().c_str());
230	
231	  const PlanResult r = run_plan(plan, disc.engines);
232	  if (!r.ok()) {
233	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
234	    return 1;
235	  }
236	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
237	  // vsim mcycle delta.
238	  const unsigned long long q_mc = r.phases[0].mcycle;
239	  const unsigned long long v_mc = r.phases[1].mcycle;
240	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
241	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
242	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
243	              elf.stem().string().c_str());
244	  return 0;
245	}
246	
247	}  // namespace
248	
249	int cmd_run(const Cli& cli) {
250	  if (cli.model.empty()) {
251	    std::fprintf(stderr,
252	                 "andesim run: --mode fast|cycle|hybrid is required "
253	                 "(pick the composition; see 'andesim run --help')\n");
254	    return 2;
255	  }
256	  if (!find_model(cli.model)) {
257	    std::fprintf(stderr,
258	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
259	                 cli.model.c_str());
260	    return 2;
261	  }
262	  if (cli.model == "fast") return run_fast(cli);
263	  if (cli.model == "cycle") return run_accurate(cli);
264	  return run_hybrid(cli);  // model validated above; only hybrid remains
265	}
266	
267	}  // namespace andes_sim
