1	#include "cli.hpp"
2	
3	namespace andes_sim {
4	namespace {
5	
6	// Try to read an option's value at args[i]. Supports both `--flag value`
7	// (consumes the next token, advancing i) and `--flag=value`.
8	//   returns  1 = matched, `out` set
9	//            0 = this token is not `flag`
10	//           -1 = matched `--flag` but no value follows
11	int match_opt(const std::vector<std::string>& args, size_t& i,
12	              const std::string& flag, std::string& out) {
13	  const std::string& a = args[i];
14	  if (a == flag) {
15	    if (i + 1 >= args.size()) return -1;
16	    out = args[++i];
17	    return 1;
18	  }
19	  const std::string pfx = flag + "=";
20	  if (a.starts_with(pfx)) {
21	    out = a.substr(pfx.size());
22	    return 1;
23	  }
24	  return 0;
25	}
26	
27	}  // namespace
28	
29	Cli parse_cli(const std::vector<std::string>& args) {
30	  Cli c;
31	  if (args.empty()) return c;  // no subcommand; caller prints usage
32	
33	  // First token is the subcommand, unless it is a top-level help request.
34	  if (args[0] == "-h" || args[0] == "--help") {
35	    c.help = true;
36	    return c;
37	  }
38	  c.subcommand = args[0];
39	
40	  for (size_t i = 1; i < args.size(); ++i) {
41	    const std::string& a = args[i];
42	
43	    if (a == "--") {  // the passthrough boundary: rest is verbatim
44	      c.has_passthrough = true;
45	      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
46	      break;
47	    }
48	    if (a == "-h" || a == "--help") {
49	      c.help = true;
50	      continue;
51	    }
52	
53	    const struct {
54	      const char* flag;
55	      std::string* out;
56	    } opts[] = {{"--mode", &c.model},
57	                {"--engine", &c.engine},
58	                {"--trigger", &c.trigger},
59	                {"--pc-start", &c.pc_start},
60	                {"--pc-end", &c.pc_end},
61	                {"--mem-size", &c.mem_size},
62	                {"--mmap-size", &c.mem_size},  // retired spelling, same knob
63	                {"--kanata", &c.kanata},
64	                {"--objdump", &c.objdump}};
65	    bool consumed = false;
66	    for (const auto& o : opts) {
67	      int r = match_opt(args, i, o.flag, *o.out);
68	      if (r < 0) { c.error = std::string("missing value for ") + o.flag; return c; }
69	      if (r > 0) { consumed = true; break; }
70	    }
71	    if (consumed) continue;
72	
73	    if (a.size() > 1 && a[0] == '-') {
74	      c.error = "unknown option: " + a;
75	      return c;
76	    }
77	    c.positional.push_back(a);
78	  }
79	
80	  return c;
81	}
82	
83	Cli parse_cli(int argc, char** argv) {
84	  std::vector<std::string> args;
85	  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
86	  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
87	  return parse_cli(args);
88	}
89	
90	}  // namespace andes_sim
