1	// Placeholder substitution for engine invoke templates -- the template-driven
2	// port of orchestrator/spawn.py (minus QEMU2). spawn.py hand-built each argv in
3	// Python; here the argv *shape* lives in each engine's `invoke` template (from
4	// `--describe`, see docs/engine_interface.md) and build_argv fills the
5	// {placeholders} from a context map. The framework thus keeps zero per-engine
6	// argv code: a new engine ships its own template.
7	#ifndef ANDESIM_ARGV_HPP
8	#define ANDESIM_ARGV_HPP
9	
10	#include <cctype>
11	#include <cstring>
12	#include <map>
13	#include <string>
14	#include <vector>
15	
16	namespace andes_sim {
17	
18	// POSIX shell-quote one arg so a rendered command line is copy-pasteable. A
19	// token of only safe characters passes through; anything else (empty, spaces,
20	// quotes, globs) is wrapped in single quotes with embedded `'` escaped as
21	// '\''. Used by render_argv for the --dry-run command preview.
22	inline std::string shell_quote(const std::string& s) {
23	  if (!s.empty()) {
24	    bool safe = true;
25	    for (char c : s)
26	      if (!std::isalnum(static_cast<unsigned char>(c)) &&
27	          !std::strchr("_@%+=:,./-", c)) {
28	        safe = false;
29	        break;
30	      }
31	    if (safe) return s;
32	  }
33	  std::string out = "'";
34	  for (char c : s) out += (c == '\'') ? "'\\''" : std::string(1, c);
35	  out += "'";
36	  return out;
37	}
38	
39	// Join an argv into one shell-quoted line (each token via shell_quote).
40	inline std::string render_argv(const std::vector<std::string>& argv) {
41	  std::string out;
42	  for (size_t i = 0; i < argv.size(); ++i) {
43	    if (i) out += ' ';
44	    out += shell_quote(argv[i]);
45	  }
46	  return out;
47	}
48	
49	// Substitute every "{key}" in `tmpl`'s args with `ctx.at(key)`. A key may
50	// appear anywhere in an arg (so "mem-path={mmap},size={mmap_size}" expands in
51	// one arg) and more than once. Recognised keys come from `ctx`; a "{key}" with
52	// no matching ctx entry is an error (returns {} and sets `err`). On success
53	// `err` is cleared and the fully-resolved argv is returned.
54	std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
55	                                    const std::map<std::string, std::string>& ctx,
56	                                    std::string& err);
57	
58	}  // namespace andes_sim
59	
60	#endif  // ANDESIM_ARGV_HPP
61

1	// The phase-plan grammar driven by run_plan (F6) -- the C++ analog of
2	// orchestrator/plan.py's Session/Step model, minus the dropped QEMU2 step.
3	//
4	// A Plan is a list of Steps; each Step names an engine (by id, resolved against
5	// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
6	// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
7	// order, threads the drained hybrid_state_v1 file forward, and returns each
8	// leg's mcycle/minstret. Under the no-QEMU2-handback design every F6 step
9	// drains, so the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg
10	// mcycle.
11	#ifndef ANDESIM_PLAN_HPP
12	#define ANDESIM_PLAN_HPP
13	
14	#include <map>
15	#include <string>
16	#include <vector>
17	
18	namespace andes_sim {
19	
20	// The ROI delimiter for a step. `kind` is marker|pc; `params` carries
21	// kind-specific values (e.g. enter_pc, exit_pc) that F9 maps onto trigger
22	// args. F6 only exercises the default marker case (no params).
23	struct Trigger {
24	  std::string kind;
25	  std::map<std::string, std::string> params;
26	};
27	
28	// One leg of a plan: which engine, which invoke role, under which trigger.
29	// `extra_args` are verbatim tokens appended after the filled template and the
30	// trigger args -- the seam for user-forwarded per-leg flags (e.g. the vsim
31	// leg's --kanata), which are orthogonal to the trigger.
32	struct Step {
33	  std::string engine_id;  // "qemu" | "vsim:ax45mpv_premium"
34	  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
35	  Trigger trigger;
36	  std::vector<std::string> extra_args{};  // default-init: keeps 3-field Step{} literals warning-free
37	};
38	
39	// A whole hybrid run. Every step loads `elf`; the shared mmap (`mem_size`
40	// bytes, at `mmap_path` or allocated by run_plan when empty) survives across
41	// every leg so memory threads through.
42	struct Plan {
43	  std::string elf;          // path to the ELF every leg launches
44	  long long mem_size = 0;   // shared-mmap size in bytes
45	  std::string mmap_path;    // "" => run_plan allocates one (F5) and owns it
46	  std::vector<Step> steps;
47	};
48	
49	// What one drain step measured (read back from its state file).
50	struct PhaseResult {
51	  unsigned long long mcycle = 0;
52	  unsigned long long minstret = 0;
53	};
54	
55	// Aggregate outcome. `error` empty => every step matched its expected exit and
56	// drained a valid state file; `phases` then holds one entry per step in order.
57	struct PlanResult {
58	  std::string error;
59	  std::vector<PhaseResult> phases;
60	  bool ok() const { return error.empty(); }
61	};
62	
63	}  // namespace andes_sim
64	
65	#endif  // ANDESIM_PLAN_HPP
66

1	// See hybrid.hpp. Builds the ROI Trigger from the CLI, resolving pc boundaries.
2	#include "hybrid.hpp"
3	
4	#include "elf_syms.hpp"
5	
6	namespace andes_sim {
7	
8	Trigger hybrid_trigger(const Cli& cli, const std::string& elf,
9	                       std::string& err) {
10	  err.clear();
11	  // --trigger is REQUIRED for hybrid: no silent default. An absent trigger used
12	  // to fall back to marker, which masked running an unmarked ELF (the fast leg
13	  // ran to completion instead of draining at the ROI, surfacing only as a
14	  // cryptic "expected exit 200, got 0"). Make the user name the ROI delimiter.
15	  if (cli.trigger.empty()) {
16	    err = "--trigger marker|pc is required "
17	          "(the ROI delimiter; see 'andesim run --help')";
18	    return {};
19	  }
20	  const std::string kind = cli.trigger;
21	
22	  if (kind == "marker") return {"marker", {}};  // markers in the workload; no params
23	
24	  if (kind == "pc") {
25	    if (cli.pc_start.empty() || cli.pc_end.empty()) {
26	      err = "trigger pc requires --pc-start and --pc-end "
27	            "(a symbol name or 0x address)";
28	      return {};
29	    }
