228	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
229	// its --jtag-port only after it has reset and halted the hart, so the debugger we
230	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
231	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
232	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
233	// single debugger slot). Returns false on timeout.
234	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
235	  constexpr int kPollMs = 50;
236	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
237	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
238	      char line[512];
239	      while (std::fgets(line, sizeof line, f)) {
240	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
241	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
242	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
243	        unsigned lport = 0, st = 0;
244	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
245	            && st == 0x0A && lport == port) {
246	          std::fclose(f);
247	          return true;
248	        }
249	      }
250	      std::fclose(f);
251	    }
252	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
253	  }
254	  return false;
255	}
