358	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
359	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
360	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
361	// driver's tests/e2e.sh delegation with a single window-cycle line.
362	int run_hybrid(const Cli& cli) {
363	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
364	  auto fail = [](const std::string& msg) {
365	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
366	    return 2;
367	  };
368	
369	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
370	
371	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
372	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
373	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
374	  const std::string elf_path = abs_elf(cli.positional[0], "--mode hybrid");
375	  if (elf_path.empty()) return 2;
376	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
377	
378	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
379	  // mistake fails fast without spawning a --describe per Verilator build.
380	  std::string err;
381	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
382	  if (!err.empty()) return fail(err);
383	
384	  // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
385	  // hybrid triggers; unknown returned an error above) -- exactly the entry
386	  // boundary --verify needs the oracle to arm on.
387	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
388	  if (!err.empty()) return fail(err);
389	
390	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
391	  if (!cli.mem_size.empty()) {
392	    std::string se;
393	    mem = parse_size(cli.mem_size, se);
394	    if (!se.empty()) return fail("--mem-size: " + se);
395	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
396	    // guest RAM here. The physical mmap reserves one V-scratch page above the
397	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
398	    // page. Failing now beats allocating a huge mmap file first and letting
399	    // QEMU die late.
400	    if (mem > max_program_mem_bytes())
401	      return fail("--mem-size " + cli.mem_size +
402	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
403	                  "reservation)");
404	  }
405	
406	  // L26/F3: refuse a run whose static image would extend into the reserved
407	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
408	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
409	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
410	  // scratch -> silent corruption. Derive the page's start from
411	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
412	  // `mem`, so the threshold tracks the reservation shape instead of relying on
413	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
414	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
415	  // reports it.
416	  {
417	    std::string e;
418	    const uint64_t top = elf_load_top(elf_path, e);
419	    const uint64_t scratch_gpa =
420	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
421	    if (e.empty() && top > scratch_gpa) {
422	      char msg[256];
423	      std::snprintf(msg, sizeof(msg),
424	                    "ELF static image ends at 0x%llx, overlapping the reserved "
425	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
426	                    "; raise --mem-size or shrink the image",
427	                    static_cast<unsigned long long>(top),
428	                    static_cast<unsigned long long>(scratch_gpa));
429	      return fail(msg);
430	    }
431	  }
432	
433	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
434	  // or the sole cycle-accurate engine (reusing the F8 selector).
435	  Discovery disc = discover_engines();
436	  const EngineDescriptor* acc =
437	      resolve_accurate_engine(disc.engines, cli.engine, err);
438	  if (!acc) {
439	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
440	    for (const std::string& w : disc.warnings)
441	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
442	    return 2;
443	  }
444	
445	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
446	  // cannot share architectural state with the rv64 fast leg).
447	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
448	  // ...and the ELF must match that engine width too (same guard as cycle).
449	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
450	    return fail(e);
451	
452	  Plan plan;
453	  plan.elf = elf_path;
454	  plan.mem_size = mem;
455	  Step qemu_step{kQemuId64, "fast-leg", trig};
456	  Step vsim_step{acc->id, "accurate-leg", trig};
457	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
458	  // #1: with no --verify the driver consumes only the vsim mcycle delta, so ask
459	  // the accurate leg to drain just the counters and skip the full register-file
460	  // readback (~190 DM abstract commands). --verify keeps the full drain so the
461	  // oracle diff sees every field. Driver policy lives here next to the rest of
462	  // the verify reasoning, not in vsim_extra_args (user-forwarded flags only).
463	  if (!cli.verify)
464	    vsim_step.extra_args.push_back("--drain-minimal");
465	  plan.steps = {qemu_step, vsim_step};
466	
467	  // Banner to stderr so the window-cycle result stands alone on stdout.
468	  // vlen is the synced value the fast leg inherits from the engine.
469	  std::fprintf(stderr,
470	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
471	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
472	               elf.stem().string().c_str());
473	
474	  PlanOptions opts;
475	  opts.dry_run = cli.dry_run;
476	  const PlanResult r = run_plan(plan, disc.engines, opts);
477	  if (!r.ok()) {
478	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
479	    return 1;
480	  }
481	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
482	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
483	  // then the vsim accurate leg -- and stop. Nothing was spawned.
484	  if (cli.dry_run) {
485	    std::vector<std::string> labels;
486	    labels.reserve(plan.steps.size());
487	    for (const Step& s : plan.steps)
488	      labels.push_back(s.role + " [" + s.engine_id + "]");
489	    return print_dry_run(r.argvs, labels);
490	  }
491	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
492	  // then anything the ROI wrote on vsim) belong to the user. The vsim
493	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
494	  // Version) -- strip it so only real program output shows, the same as `cycle`
495	  // does; its [info] log is already absent (the leg's stderr was dropped at
496	  // capture). The QEMU leg has no banner, so it relays verbatim.
497	  for (size_t i = 0; i < r.phases.size(); ++i) {
498	    const std::string& out = r.phases[i].out;
499	    if (out.empty()) continue;
500	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
501	      const std::string shown = strip_vsim_banner(out);
502	      std::fwrite(shown.data(), 1, shown.size(), stdout);
503	    } else {
504	      std::fwrite(out.data(), 1, out.size(), stdout);
505	    }
506	  }
507	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
508	  // vsim mcycle delta.
509	  {
510	    const unsigned long long q_mc = r.phases[0].mcycle;
511	    const unsigned long long v_mc = r.phases[1].mcycle;
512	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
513	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
514	  }
515	
516	  // v6 incompatibility surface: the QEMU1 drain's write-mask records which
517	  // config CSRs the program actually wrote; any of them this engine does not
518	  // implement would TRAP on its silicon (the program would never reach the
519	  // ROI), yet the hybrid restore silently skipped it. Warn -- the figure may
520	  // not represent this engine running this program.
521	  {
522	    const std::string w = unsupported_written_warning(
523	        r.phases[0].st, acc->andes_csrs, acc->id);
524	    if (!w.empty()) std::fputs(w.c_str(), stderr);
525	  }
526	
527	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
528	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
529	  // halt pc, and diff the two drains in-process. The oracle plan gets its
530	  // own fresh mmap: reusing the main run's would boot the oracle on the
531	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
532	  // output was already relayed from the main run.
533	  if (cli.verify) {
534	    char pcbuf[32];
535	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
536	                  static_cast<unsigned long long>(r.phases[1].st.pc));
537	    Trigger vtrig;
538	    vtrig.kind = "verify-" + trig.kind;
539	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
540	    vtrig.params["drain_pc"] = pcbuf;
541	
542	    Plan vplan;
543	    vplan.elf = elf_path;
544	    vplan.mem_size = mem;
545	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
546	
547	    std::fprintf(stderr,
548	                 "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
549	                 "exit, pc=%s)\n",
550	                 pcbuf);
551	    const PlanResult vr = run_plan(vplan, disc.engines);
552	    if (!vr.ok()) {
553	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
554	      return 1;
555	    }
556	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
557	    // engine does not implement (it never restored/re-read them; comparing
558	    // would false-diff). Mirrors the resume/drain gating in vsim.
559	    const DiffReport d =
560	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
561	    print_diff_report(d);
562	    if (!d.ok()) {
563	      std::fprintf(stderr,
564	                   "andesim run --verify: vsim drain diverges from the "
565	                   "QEMU oracle\n");
566	      return 1;
567	    }
568	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
569	  }
570	
571	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
572	              elf.stem().string().c_str());
573	  return 0;
574	}
