commit bf7d2494659c8764a93d7e27b73b948bf29a529a
Author: Nick Hung <nick@andestech.com>
Date:   Tue Jun 16 14:09:32 2026 +0800

    behavioral: reject --trigger/--pc-start/--pc-end on fast/cycle

    These delimit the hybrid ROI window. fast and cycle run the whole
    program and silently ignored them, so `run --model cycle --trigger pc
    --pc-start S --pc-end E` returned a whole-program cycle figure for the
    window the user asked for, with no warning. Now rejected with rc 2 and a
    message pointing at --model hybrid.

    Exception: --pc-start doubles as the cycle lock-step arm pc, so
    `--model cycle --cosim --pc-start` stays valid (cosim_redesign F6).

    Test: tests/andes_sim/test_andes_sim_trigger_gating.sh (RED -> GREEN) --
    fast/cycle reject all three flags; cycle --cosim --pc-start and hybrid
    --trigger pc both pass the gate and reach the ELF check.

    Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>

diff --git a/driver/cmd_run.cpp b/driver/cmd_run.cpp
index 076d60d..9eb8c2e 100644
--- a/driver/cmd_run.cpp
+++ b/driver/cmd_run.cpp
@@ -748,6 +748,30 @@ int cmd_run(const Cli& cli) {
                  "--cosim (cycle lock-step is already instruction-exact)\n");
     return 2;
   }
+  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window; fast and
+  // cycle run the whole program and would silently drop them, handing back a
+  // whole-program figure for the window the user asked for. Reject instead.
+  // Exception: --pc-start doubles as the cycle lock-step arm pc under
+  // --model cycle --cosim (run_cosim_lockstep), so it stays valid there.
+  if (!cli.trigger.empty() && cli.model != "hybrid") {
+    std::fprintf(stderr,
+                 "andes-sim run: --trigger applies only to --model hybrid "
+                 "(the ROI delimiter); fast/cycle run the whole program\n");
+    return 2;
+  }
+  if (!cli.pc_end.empty() && cli.model != "hybrid") {
+    std::fprintf(stderr,
+                 "andes-sim run: --pc-end applies only to --model hybrid "
+                 "--trigger pc\n");
+    return 2;
+  }
+  if (!cli.pc_start.empty() && cli.model != "hybrid" &&
+      !(cli.model == "cycle" && cli.cosim)) {
+    std::fprintf(stderr,
+                 "andes-sim run: --pc-start applies only to --model hybrid "
+                 "--trigger pc (or --model cycle --cosim)\n");
+    return 2;
+  }
   if (cli.model == "fast") return run_fast(cli);
   if (cli.model == "cycle") return run_accurate(cli);
   return run_hybrid(cli);  // model validated above; only hybrid remains
