93	std::vector<std::vector<std::string>> plan_argvs(
94	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
95	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
96	  std::vector<std::vector<std::string>> out;
97	  out.reserve(plan.steps.size());
98	  std::string prev_state_out;  // empty for the cold first leg
99	
100	  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
101	  long vlen = 0;
102	  for (const Step& s : plan.steps)
103	    if (s.role == "accurate-leg")
104	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
105	        if (e->vlen > 0) vlen = e->vlen;
106	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
107	
108	  for (size_t i = 0; i < plan.steps.size(); ++i) {
109	    const Step& step = plan.steps[i];
110	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
111	    if (!eng) {
112	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
113	            step.engine_id + "'";
114	      return {};
115	    }
116	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
117	    if (!tmpl) {
118	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
119	            "' has no invoke template for role '" + step.role + "'";
120	      return {};
121	    }
122	
123	    std::string trig_err;
124	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
125	    if (!trig_err.empty()) {
126	      err = "plan step " + std::to_string(i) + ": " + trig_err;
127	      return {};
128	    }
129	
130	    const std::string state_out = state_path(workdir, i);
131	    const std::map<std::string, std::string> m = {
132	        {"bin", eng->bin_path},
133	        {"elf", plan.elf},
134	        {"plugin", ctx.plugin_path},
135	        {"mmap", ctx.mmap_path},
136	        {"mmap_size", std::to_string(ctx.mem_size)},
137	        {"mmap_base", ctx.mmap_base},
138	        {"state_in", prev_state_out},
139	        {"state_out", state_out},
140	        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for marker)
141	        {"vlen", vlen_str},
142	    };
143	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
144	    if (!err.empty()) {
145	      err = "plan step " + std::to_string(i) + ": " + err;
146	      return {};
147	    }
148	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
149	    // after the filled template (matches tests/e2e.sh's ordering).
150	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
151	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
152	    out.push_back(std::move(argv));
153	    prev_state_out = state_out;
154	  }
155	  err.clear();
156	  return out;
157	}
