159	PlanResult run_plan(const Plan& plan,
160	                    const std::vector<EngineDescriptor>& engines,
161	                    const PlanOptions& opts) {
162	  PlanResult res;
163	  if (plan.steps.empty()) {
164	    res.error = "plan has no steps";
165	    return res;
166	  }
167	
168	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
169	  std::string mmap_path = plan.mmap_path;
170	  const bool own_mmap = mmap_path.empty();
171	  if (own_mmap) {
172	    std::string err;
173	    mmap_path = allocate(plan.mem_size, err);
174	    if (mmap_path.empty()) {
175	      res.error = err;
176	      return res;
177	    }
178	  }
179	
180	  // A private dir for the threaded drain files.
181	  std::error_code ec;
182	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
183	  std::string tmpl = workdir.string();
184	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
185	  tbuf.push_back('\0');
186	  const char* made = ::mkdtemp(tbuf.data());
187	  if (!made) {
188	    if (own_mmap) ::unlink(mmap_path.c_str());
189	    res.error = "failed to create plan work dir";
190	    return res;
191	  }
192	  const std::string wd = made;
193	
194	  RuntimeCtx ctx;
195	  ctx.mmap_path = mmap_path;
196	  ctx.mem_size = plan.mem_size;
197	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
198	
199	  std::string err;
200	  const std::vector<std::vector<std::string>> argvs =
201	      plan_argvs(plan, engines, wd, ctx, err);
202	  if (!err.empty()) {
203	    res.error = err;
204	  } else {
205	    for (size_t i = 0; i < argvs.size(); ++i) {
206	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
207	      if (r.spawn_failed) {
208	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
209	        break;
210	      }
211	      if (r.timed_out) {
212	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
213	                    std::to_string(opts.timeout_ms) + " ms";
214	        break;
215	      }
216	      if (r.rc != opts.expect_rc) {
217	        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
218	        break;
219	      }
220	      const StateFile sf = read_state_file(state_path(wd, i));
221	      if (!sf.ok()) {
222	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
223	        break;
224	      }
225	      res.phases.push_back({sf.st.mcycle, sf.st.minstret});
226	    }
227	  }
228	
229	  fs::remove_all(wd, ec);
230	  if (own_mmap) ::unlink(mmap_path.c_str());
231	  return res;
232	}
