1	// Unit tests for resolve_pc (F9): the pc-trigger boundary resolver. A boundary
2	// is either a "0x"-prefixed hex address (used verbatim, prefix stripped) or a
3	// symbol name looked up in the ELF .symtab -> st_value. C++ port of
4	// tests/lib/roi.sh:resolve_pc, but reading the symtab directly (no `nm`).
5	//
6	// Fixtures are real built ELFs: handoff_roundtrip.elf defines `_start` at
7	// 0x100000 (a stable linker-script entry). Plain assert-and-count harness.
8	#include <string>
9	
10	#include "elf_syms.hpp"
11	#include "repo_root.hpp"
12	#include "test_check.hpp"
13	
14	using namespace andes_sim;
15	
16	int main() {
17	  const std::string elf =
18	      (repo_root() / "tests" / "fixtures" / "handoff_roundtrip.elf").string();
19	
20	  // A 0x address resolves to itself with the prefix stripped (verbatim, no
21	  // symtab touched) -- matches roi.sh `${boundary#0[xX]}`.
22	  {
23	    std::string err;
24	    CHECK(resolve_pc(elf, "0x100000", err) == "100000");
25	    CHECK(err.empty());
26	  }
27	  // 0X (capital) prefix is also stripped; the remaining digits are kept as-is.
28	  {
29	    std::string err;
30	    CHECK(resolve_pc(elf, "0X1ABC", err) == "1ABC");
31	    CHECK(err.empty());
32	  }
33	  // A defined symbol resolves to its st_value as bare lowercase hex.
34	  {
35	    std::string err;
36	    CHECK(resolve_pc(elf, "_start", err) == "100000");
37	    CHECK(err.empty());
38	  }
39	  // An undefined symbol is a hard error (empty result + message naming it).
40	  {
41	    std::string err;
42	    CHECK(resolve_pc(elf, "definitely_not_a_symbol_xyz", err).empty());
43	    CHECK(!err.empty());
44	    CHECK(err.find("definitely_not_a_symbol_xyz") != std::string::npos);
45	  }
46	  // An unreadable ELF is an error, not a crash.
47	  {
48	    std::string err;
49	    CHECK(resolve_pc("/no/such/file.elf", "_start", err).empty());
50	    CHECK(!err.empty());
51	  }
52	
53	  return andes_sim::test::report("elf-syms");
54	}
